insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'f4523abc-cc13-426c-9eed-deef288ff03d'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Energy stores and calculating energy changes', 'A 2 kg trolley moves at 3 m/s. How much energy is in its kinetic energy store?', '3 J', '18 J', '6 J', '9 J', 'D', 'Ek = ½mv² = ½ × 2 × 3² = 9 J. Forgetting to square the speed gives 3 J; forgetting the ½ gives 18 J.', 'foundation', 'calculation', 'AO2'),
  (2, 'Energy stores and calculating energy changes', 'A 50 kg student climbs 2.0 m up a ladder. How much energy is transferred to their gravitational potential energy store? (g = 9.8 N/kg)', '490 J', '980 J', '100 J', '9800 J', 'B', 'Ep = mgh = 50 × 9.8 × 2.0 = 980 J.', 'foundation', 'calculation', 'AO2'),
  (3, 'Energy stores and calculating energy changes', 'A spring with spring constant 200 N/m is stretched by 0.10 m. How much energy is stored in it?', '1.0 J', '20 J', '2.0 J', '10 J', 'A', 'Ee = ½ke² = ½ × 200 × 0.10² = 1.0 J. Forgetting to square the extension gives 10 J.', 'foundation', 'calculation', 'AO2'),
  (4, 'Energy stores and calculating energy changes', 'A ball is dropped from a height of 5.0 m. Ignoring air resistance, how fast is it moving just before it hits the ground? (g = 9.8 N/kg)', '98 m/s', '9.9 m/s', '7.0 m/s', '49 m/s', 'B', 'All the gravitational potential energy becomes kinetic energy: mgh = ½mv², so v = √(2gh) = √(2 × 9.8 × 5.0) = √98 ≈ 9.9 m/s. The mass cancels out.', 'higher', 'calculation', 'AO3'),
  (5, 'Energy stores and calculating energy changes', 'A moving car brakes and comes to a stop. Which energy store increases?', 'The thermal energy store of the brakes and surroundings', 'The gravitational potential energy store of the car', 'The chemical energy store of the fuel', 'The kinetic energy store of the car', 'A', 'Friction in the brakes transfers energy from the car''s kinetic store to the thermal store of the brakes, which then dissipates to the surroundings.', 'foundation', 'applied', 'AO2'),
  (6, 'Specific heat capacity', 'How much energy is needed to raise the temperature of 2.0 kg of water by 10 °C? (specific heat capacity of water = 4200 J/kg °C)', '84 000 J', '8400 J', '42 000 J', '840 000 J', 'A', 'ΔE = mcΔθ = 2.0 × 4200 × 10 = 84 000 J.', 'foundation', 'calculation', 'AO2'),
  (7, 'Specific heat capacity', 'What is meant by the specific heat capacity of a substance?', 'The temperature at which the substance starts to boil', 'The energy needed to change the state of 1 kg of the substance without changing its temperature', 'The energy needed to raise the temperature of 1 kg of the substance by 1 °C', 'The total energy stored in 1 kg of the substance', 'C', 'Specific heat capacity is about temperature change. Changing state with no temperature change is specific latent heat.', 'foundation', 'recall', 'AO1'),
  (8, 'Specific heat capacity', 'A 1.0 kg metal block is supplied with 9000 J of energy and its temperature rises by 10 °C. What is its specific heat capacity?', '900 J/kg °C', '90 J/kg °C', '90 000 J/kg °C', '9000 J/kg °C', 'A', 'c = ΔE ÷ (mΔθ) = 9000 ÷ (1.0 × 10) = 900 J/kg °C.', 'foundation', 'calculation', 'AO2'),
  (9, 'Specific heat capacity', 'In the specific heat capacity practical, why is the metal block wrapped in insulation?', 'To increase the specific heat capacity of the block', 'To increase the energy supplied by the heater', 'To make the thermometer respond faster', 'To reduce energy transfer to the surroundings, so the calculated value is more accurate', 'D', 'Without insulation some energy heats the surroundings rather than the block, so the temperature rise is smaller and the calculated specific heat capacity is too high.', 'foundation', 'applied', 'AO2'),
  (10, 'Power', 'What is power?', 'The total energy transferred by a device', 'The force multiplied by the distance moved', 'The rate at which energy is transferred or work is done', 'The energy wasted by a device each second', 'C', 'Power = energy transferred ÷ time (P = E/t) or work done ÷ time (P = W/t). It is measured in watts, where 1 W = 1 J/s.', 'foundation', 'recall', 'AO1'),
  (11, 'Power', 'A motor transfers 6000 J of energy in 2 minutes. What is its power?', '100 W', '3000 W', '12 000 W', '50 W', 'D', 'Time must be in seconds: 2 minutes = 120 s. P = E/t = 6000 ÷ 120 = 50 W. Using 2 instead of 120 gives 3000 W.', 'foundation', 'calculation', 'AO2'),
  (12, 'Power', 'Two kettles each boil the same mass of water from the same starting temperature. Kettle A takes 2 minutes and kettle B takes 3 minutes. Which kettle is more powerful?', 'Kettle A, because it transfers the same energy in less time', 'Neither, because they transfer the same amount of energy', 'Kettle B, because it heats the water for longer', 'Kettle B, because it transfers more energy', 'A', 'Both kettles transfer about the same energy to the water, but a more powerful kettle transfers it at a higher rate, so it finishes sooner.', 'foundation', 'applied', 'AO3'),
  (13, 'Conservation, dissipation and efficiency', 'Which statement about energy is always true?', 'Wasted energy is destroyed', 'Energy can be transferred usefully, stored or dissipated, but it cannot be created or destroyed', 'Energy is used up when a device is switched on', 'An efficient device creates extra energy', 'B', 'This is the principle of conservation of energy. Wasted energy is not destroyed; it is dissipated, usually to thermal stores of the surroundings.', 'foundation', 'recall', 'AO1'),
  (14, 'Conservation, dissipation and efficiency', 'A motor is supplied with 200 J of energy and transfers 50 J usefully. What is its efficiency?', '150%', '25%', '75%', '4%', 'B', 'Efficiency = useful output ÷ total input = 50 ÷ 200 = 0.25 = 25%.', 'foundation', 'calculation', 'AO2'),
  (15, 'Conservation, dissipation and efficiency', 'A 60 W lamp has an efficiency of 0.15. What is its useful power output?', '0.25 W', '400 W', '51 W', '9 W', 'D', 'Useful power output = efficiency × total power input = 0.15 × 60 = 9 W. The other 51 W is wasted.', 'higher', 'calculation', 'AO2'),
  (16, 'Conservation, dissipation and efficiency', 'Which change would reduce the rate of energy loss through the walls of a house?', 'Leaving the windows open', 'Making the walls thinner', 'Using cavity wall insulation, which has a low thermal conductivity', 'Using bricks with a higher thermal conductivity', 'C', 'The rate of energy transfer through a wall is lower if the wall is thicker and has a lower thermal conductivity.', 'foundation', 'applied', 'AO2'),
  (17, 'National and global energy resources', 'Which of these is a renewable energy resource?', 'Nuclear fuel', 'Natural gas', 'Coal', 'Wind', 'D', 'Renewable resources are replenished as they are used. Coal, gas and nuclear fuel are finite.', 'foundation', 'recall', 'AO1'),
  (18, 'National and global energy resources', 'What is a disadvantage of generating electricity using wind turbines?', 'They use up a finite fuel', 'They cannot be used in the UK', 'They release carbon dioxide while generating', 'They are unreliable, because the output depends on the weather', 'D', 'Wind turbines produce no carbon dioxide while running and use no fuel, but they generate nothing when there is no wind.', 'foundation', 'applied', 'AO2'),
  (19, 'National and global energy resources', 'Which energy resource produces no carbon dioxide when generating electricity, but produces radioactive waste?', 'Biofuel', 'Hydroelectric power', 'Nuclear fuel', 'Coal', 'C', 'Nuclear power stations don''t burn fuel, so they release no carbon dioxide while generating, but the used fuel is radioactive and must be stored safely for a long time.', 'foundation', 'recall', 'AO1'),
  (20, 'National and global energy resources', 'Biofuels are sometimes described as carbon neutral. What is the reason for this?', 'The plants absorb carbon dioxide as they grow, balancing the carbon dioxide released when the fuel is burned', 'Biofuels release no carbon dioxide when they are burned', 'Biofuels are burned at a low temperature', 'Biofuels are made from fossil fuels', 'A', 'Burning a biofuel does release carbon dioxide, but the crops took in a similar amount as they grew, so in theory there is no overall increase.', 'higher', 'applied', 'AO3')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
