insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'f4523abc-cc13-426c-9eed-deef288ff03d'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Charge and current', 'A current of 2.0 A flows for 30 s. How much charge flows?', '0.067 C', '60 C', '32 C', '15 C', 'B', 'Q = It = 2.0 × 30 = 60 C.', 'foundation', 'calculation', 'AO2'),
  (2, 'Charge and current', 'In a single closed loop (a series circuit), how does the current at different points compare?', 'It gets smaller after each component', 'It is the same at every point in the loop', 'It is largest next to the positive terminal', 'It is zero after the first component', 'B', 'Current is the rate of flow of charge. Charge isn''t used up, so the current is the same everywhere in a single loop.', 'foundation', 'recall', 'AO1'),
  (3, 'Charge and current', 'What is electric current?', 'The energy transferred per unit charge', 'The total number of electrons in a wire', 'The rate of flow of electrical charge', 'The opposition to the flow of charge', 'C', 'Current is the rate of flow of charge (I = Q/t). Energy per unit charge is potential difference, and opposition to current is resistance.', 'foundation', 'recall', 'AO1'),
  (4, 'Resistance and I-V characteristics', 'A current of 0.50 A flows through a 12 Ω resistor. What is the potential difference across it?', '6.0 V', '0.042 V', '12.5 V', '24 V', 'A', 'V = IR = 0.50 × 12 = 6.0 V.', 'foundation', 'calculation', 'AO2'),
  (5, 'Resistance and I-V characteristics', 'Why does the resistance of a filament lamp increase as the current through it increases?', 'The filament gets colder', 'The filament becomes shorter', 'Fewer electrons can flow through it', 'The filament gets hotter, which increases its resistance', 'D', 'As the current increases the filament heats up. The ions in the metal vibrate more, making it harder for electrons to pass, so the resistance rises.', 'foundation', 'recall', 'AO1'),
  (6, 'Resistance and I-V characteristics', 'Which statement describes a diode?', 'Its resistance falls as light intensity increases', 'Its resistance stays constant at a constant temperature', 'Current flows through it in one direction only', 'Its resistance falls as temperature increases', 'C', 'A diode has a very high resistance in the reverse direction. The other options describe an LDR, a thermistor and an ohmic conductor.', 'foundation', 'recall', 'AO1'),
  (7, 'Resistance and I-V characteristics', 'A thermistor is part of a circuit. The temperature of the thermistor increases. What happens to its resistance?', 'It stays the same', 'It falls to zero', 'It decreases', 'It increases', 'C', 'A thermistor''s resistance decreases as its temperature increases, which is why it is used in temperature sensors and thermostats.', 'foundation', 'applied', 'AO2'),
  (8, 'Series and parallel circuits', 'A 4 Ω resistor and a 6 Ω resistor are connected in series. What is the total resistance?', '10 Ω', '1.5 Ω', '2.4 Ω', '24 Ω', 'A', 'In series, resistances add: R = R₁ + R₂ = 4 + 6 = 10 Ω. 2.4 Ω would be the combined resistance in parallel.', 'foundation', 'calculation', 'AO2'),
  (9, 'Series and parallel circuits', 'A second resistor is added in parallel with a resistor in a circuit. What happens to the total resistance of the circuit?', 'It increases', 'It decreases', 'It stays the same', 'It doubles', 'B', 'Adding a parallel branch gives the charge another path, so the total resistance is less than the smallest individual resistance.', 'foundation', 'recall', 'AO1'),
  (10, 'Series and parallel circuits', 'Two identical lamps are connected in series with a 12 V battery. What is the potential difference across each lamp?', '6 V', '3 V', '12 V', '24 V', 'A', 'In series, the potential difference of the supply is shared between components. Identical lamps share it equally: 12 ÷ 2 = 6 V.', 'foundation', 'applied', 'AO2'),
  (11, 'Series and parallel circuits', 'A 6 Ω resistor and a 3 Ω resistor are connected in series to a 9 V supply. What is the potential difference across the 6 Ω resistor?', '4.5 V', '9 V', '6 V', '3 V', 'C', 'Total resistance = 9 Ω, so I = V/R = 9 ÷ 9 = 1 A. Across the 6 Ω resistor, V = IR = 1 × 6 = 6 V. The larger resistor takes the larger share of the pd.', 'higher', 'calculation', 'AO2'),
  (12, 'Domestic uses and safety', 'What is the mains electricity supply in the UK?', 'Alternating current at 50 V and 230 Hz', 'Direct current at 230 V and 50 Hz', 'Alternating current at 230 V and 50 Hz', 'Direct current at 12 V', 'C', 'UK mains is an a.c. supply with a frequency of 50 Hz and a potential difference of about 230 V.', 'foundation', 'recall', 'AO1'),
  (13, 'Domestic uses and safety', 'In a three-core mains cable, what colour is the live wire?', 'Brown', 'Blue', 'Green and yellow stripes', 'Grey', 'A', 'Live is brown, neutral is blue and earth is green and yellow stripes.', 'foundation', 'recall', 'AO1'),
  (14, 'Domestic uses and safety', 'Why can a person get an electric shock by touching the live wire?', 'The earth wire carries a current all the time', 'The live wire is at 0 V', 'Their body is at 0 V, so there is a large potential difference between the live wire and their body, causing a current through them', 'The neutral wire is at 230 V', 'C', 'The live wire is at about 230 V and the person is at or near earth potential (0 V). The large potential difference drives a current through the body.', 'higher', 'applied', 'AO3'),
  (15, 'Power, energy transfers and the National Grid', 'A device is connected to a 230 V supply and draws a current of 2.0 A. What is its power?', '232 W', '115 W', '460 W', '0.0087 W', 'C', 'P = VI = 230 × 2.0 = 460 W.', 'foundation', 'calculation', 'AO2'),
  (16, 'Power, energy transfers and the National Grid', 'A 2.0 kW heater is switched on for 30 minutes. How much energy does it transfer?', '3 600 000 J', '3600 J', '60 000 J', '1000 J', 'A', 'E = Pt, with power in watts and time in seconds: 2000 W × 1800 s = 3 600 000 J. Using 30 instead of 1800 gives 60 000 J.', 'foundation', 'calculation', 'AO2'),
  (17, 'Power, energy transfers and the National Grid', 'Why do step-up transformers increase the potential difference before electricity is sent across the National Grid?', 'To reduce the current, so less energy is lost heating the cables', 'To increase the current so the electricity travels faster', 'To change alternating current into direct current', 'To reduce the potential difference for safety in homes', 'A', 'For the same power, a higher pd means a lower current. Lower current means less heating of the cables, so transmission is more efficient. Step-down transformers lower the pd for homes.', 'foundation', 'recall', 'AO1'),
  (18, 'Power, energy transfers and the National Grid', 'A current of 3.0 A flows through a 10 Ω resistor. What is the power transferred in the resistor?', '30 W', '300 W', '0.9 W', '90 W', 'D', 'P = I²R = 3.0² × 10 = 90 W. Forgetting to square the current gives 30 W.', 'higher', 'calculation', 'AO2'),
  (19, 'Static electricity', 'A polythene rod becomes negatively charged when it is rubbed with a cloth. What has happened?', 'Positive charges have moved from the rod to the cloth', 'Electrons have been transferred from the cloth to the rod', 'Electrons have been created on the rod', 'Protons have been transferred from the rod to the cloth', 'B', 'Only electrons move when insulators are rubbed together. The rod gains electrons and becomes negative; the cloth loses electrons and becomes positive.', 'foundation', 'recall', 'AO1'),
  (20, 'Static electricity', 'Two negatively charged objects are brought close together. What happens?', 'They both become neutral', 'There is no force between them', 'They attract each other', 'They repel each other', 'D', 'Like charges repel and unlike charges attract. The force acts without the objects touching.', 'foundation', 'recall', 'AO1')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
