insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'f4523abc-cc13-426c-9eed-deef288ff03d'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Density and changes of state', 'A block has a mass of 600 kg and a volume of 0.20 m³. What is its density?', '120 kg/m³', '3000 kg/m³', '600 kg/m³', '0.00033 kg/m³', 'B', 'ρ = m/V = 600 ÷ 0.20 = 3000 kg/m³.', 'foundation', 'calculation', 'AO2'),
  (2, 'Density and changes of state', 'Why are gases much less dense than solids?', 'Each of their particles contains fewer atoms', 'Their particles move more slowly', 'Their particles are much further apart', 'Their particles are lighter', 'C', 'The same mass of particles takes up a much larger volume in a gas because the particles are spread far apart.', 'foundation', 'recall', 'AO1'),
  (3, 'Density and changes of state', 'When a block of ice melts, what happens to its mass?', 'It increases', 'It halves', 'It stays the same', 'It decreases', 'C', 'Changes of state conserve mass: the number of particles doesn''t change, only their arrangement.', 'foundation', 'recall', 'AO1'),
  (4, 'Density and changes of state', 'What is the best way to find the volume of an irregularly shaped stone so you can calculate its density?', 'Weigh it while it is underwater', 'Measure the volume of water it displaces', 'Heat it and measure how much it expands', 'Measure its length, width and height with a ruler', 'B', 'Lower the stone into a eureka can or measuring cylinder; the volume of water displaced equals the volume of the stone.', 'foundation', 'applied', 'AO2'),
  (5, 'Density and changes of state', 'What is sublimation?', 'Changing from a liquid to a gas', 'Changing directly from a solid to a gas', 'Changing from a solid to a liquid', 'Changing from a gas to a liquid', 'B', 'Sublimation skips the liquid state. The other options are condensing, evaporating or boiling, and melting.', 'foundation', 'recall', 'AO1'),
  (6, 'Density and changes of state', 'A block measures 2.0 cm × 3.0 cm × 5.0 cm and has a mass of 81 g. What is its density?', '2430 g/cm³', '27 g/cm³', '0.37 g/cm³', '2.7 g/cm³', 'D', 'Volume = 2.0 × 3.0 × 5.0 = 30 cm³. ρ = m/V = 81 ÷ 30 = 2.7 g/cm³.', 'foundation', 'calculation', 'AO2'),
  (7, 'Density and changes of state', 'How is a change of state different from a chemical change?', 'A change of state produces a new substance', 'A change of state is physical: if it is reversed, the material recovers its original properties', 'A change of state always changes the mass', 'A change of state can never be reversed', 'B', 'Changes of state are physical changes. No new substance is made and mass is conserved.', 'foundation', 'recall', 'AO1'),
  (8, 'Internal energy and specific latent heat', 'What is the internal energy of a system?', 'The temperature of the system', 'The energy needed to melt the system', 'The total kinetic energy and potential energy of all the particles in the system', 'Only the kinetic energy of the particles', 'C', 'Internal energy is the energy stored by the particles: kinetic energy from their motion plus potential energy from the forces between them.', 'foundation', 'recall', 'AO1'),
  (9, 'Internal energy and specific latent heat', 'What is the specific latent heat of a substance?', 'The energy needed to raise the temperature of 1 kg of the substance by 1 °C', 'The energy needed to change the state of 1 kg of the substance with no change in temperature', 'The energy needed to boil any mass of the substance', 'The energy released when 1 kg of the substance burns', 'B', 'Specific latent heat concerns changes of state. Raising temperature by 1 °C is specific heat capacity.', 'foundation', 'recall', 'AO1'),
  (10, 'Internal energy and specific latent heat', 'How much energy is needed to melt 0.50 kg of ice at 0 °C? (specific latent heat of fusion of ice = 334 000 J/kg)', '16 700 J', '668 000 J', '334 000 J', '167 000 J', 'D', 'E = mL = 0.50 × 334 000 = 167 000 J. Dividing instead of multiplying gives 668 000 J.', 'foundation', 'calculation', 'AO2'),
  (11, 'Internal energy and specific latent heat', 'While a solid is melting, its temperature stays constant even though it is still being heated. Why?', 'The particles stop moving while it melts', 'Energy is lost to the surroundings exactly as fast as it is supplied', 'No energy is being supplied while it melts', 'The energy supplied increases the potential energy of the particles by breaking bonds, not their kinetic energy', 'D', 'During a change of state, energy goes into overcoming the forces between particles (potential energy). Temperature is linked to the particles'' kinetic energy, so it doesn''t change.', 'higher', 'applied', 'AO3'),
  (12, 'Internal energy and specific latent heat', 'A heating curve for water shows a flat section at 100 °C. What is happening during this section?', 'The steam is condensing', 'The water is freezing', 'The water is boiling, changing from liquid to gas', 'The ice is melting', 'C', 'Flat sections on a heating curve are changes of state. At 100 °C water boils.', 'foundation', 'applied', 'AO2'),
  (13, 'Internal energy and specific latent heat', 'The specific latent heat of vaporisation of water is 2.26 MJ/kg. How much energy is needed to turn 0.20 kg of boiling water into steam?', '0.452 MJ', '2.26 MJ', '0.226 MJ', '11.3 MJ', 'A', 'E = mL = 0.20 × 2.26 = 0.452 MJ.', 'foundation', 'calculation', 'AO2'),
  (14, 'Internal energy and specific latent heat', 'Steam at 100 °C causes worse burns than the same mass of water at 100 °C. Why?', 'Steam releases its latent heat as it condenses on the skin, as well as the energy released as it cools', 'Water at 100 °C cannot transfer energy to skin', 'Steam is at a higher temperature than water at 100 °C', 'Steam has a higher specific heat capacity than water', 'A', 'When steam condenses it transfers a large amount of energy (its latent heat of vaporisation) to the skin before the resulting water cools.', 'higher', 'applied', 'AO3'),
  (15, 'Particle motion in gases and gas pressure', 'What causes the pressure of a gas in a container?', 'Gas particles expanding as they heat up', 'Gas particles attracting each other', 'The weight of the container', 'Gas particles colliding with the walls of the container', 'D', 'Each collision exerts a force on the wall. The total force per unit area is the gas pressure.', 'foundation', 'recall', 'AO1'),
  (16, 'Particle motion in gases and gas pressure', 'A gas is heated in a sealed container with a fixed volume. What happens to its pressure?', 'It increases, because the particles move faster and hit the walls harder and more often', 'It increases, because the particles get bigger', 'It decreases, because the particles spread out', 'It stays the same, because the volume is fixed', 'A', 'Higher temperature means higher average kinetic energy, so collisions with the walls are more frequent and more forceful.', 'foundation', 'applied', 'AO3'),
  (17, 'Particle motion in gases and gas pressure', 'A gas at a constant temperature has a pressure of 100 kPa in a volume of 2.0 m³. It is compressed to 0.50 m³. What is its new pressure?', '25 kPa', '400 kPa', '200 kPa', '100 kPa', 'B', 'At constant temperature, pV is constant: 100 × 2.0 = p × 0.50, so p = 400 kPa. Volume is a quarter, so pressure is four times bigger.', 'higher', 'calculation', 'AO2'),
  (18, 'Particle motion in gases and gas pressure', 'Pumping up a bicycle tyre quickly makes the air in the pump warmer. Why?', 'Work is done on the gas, which increases its internal energy and so its temperature', 'The gas loses particles as it is pumped', 'Friction between gas particles cools the pump', 'The pressure of the gas falls', 'A', 'Pushing the piston in does work on the gas. This transfers energy to the gas, raising its internal energy and temperature.', 'higher', 'applied', 'AO2'),
  (19, 'Particle motion in gases and gas pressure', 'How do the particles in a gas move?', 'Randomly, in all directions, at a range of speeds', 'Sliding past each other while staying in contact', 'Vibrating about fixed positions', 'All at the same speed in straight lines in one direction', 'A', 'Gas particles move randomly and constantly at a range of speeds. Vibrating about fixed positions describes a solid; sliding past each other describes a liquid.', 'foundation', 'recall', 'AO1'),
  (20, 'Particle motion in gases and gas pressure', 'A fixed mass of gas is allowed to expand into a larger volume at constant temperature. What happens to its pressure?', 'It decreases, because the particles slow down', 'It decreases, because the particles hit the walls less often', 'It stays the same, because the temperature is constant', 'It increases, because the particles have more space to speed up', 'B', 'With the same particles in a larger volume, collisions with each unit area of wall happen less often. The particles'' speed is unchanged because the temperature is constant.', 'foundation', 'applied', 'AO3')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Particle Model of Matter') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

insert into quizzes (topic_id, title, display_order, question_count, cooldown_hours) values ((select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Particle Model of Matter'), 'Quiz 1', 1, 0, 168);
