insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Atomic Structure'), 'Radioactive decay, nuclear radiation and nuclear equations', '4.4.2.1-4.4.2.3', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Atomic Structure'), 'Half-life, contamination and irradiation', '4.4.2.4-4.4.2.5', 3);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Atomic Structure'), 'Background radiation, uses of radiation, fission and fusion', '4.4.3-4.4.4', 4);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'f4523abc-cc13-426c-9eed-deef288ff03d'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Atoms, isotopes and the development of the atomic model', 'What is the approximate radius of an atom?', '1 × 10⁻¹⁴ m', '1 × 10⁻⁶ m', '1 × 10⁻¹⁰ m', '1 × 10⁻³ m', 'C', 'Atoms have a radius of about 1 × 10⁻¹⁰ m. The nucleus is about 10 000 times smaller (around 1 × 10⁻¹⁴ m).', 'foundation', 'recall', 'AO1'),
  (2, 'Atoms, isotopes and the development of the atomic model', 'What did the plum pudding model suggest an atom was like?', 'A ball of positive charge with negative electrons embedded in it', 'A tiny positive nucleus surrounded by mostly empty space', 'A tiny solid sphere that cannot be divided', 'Electrons orbiting a nucleus at fixed distances', 'A', 'The plum pudding model followed the discovery of the electron. Alpha scattering later replaced it with the nuclear model.', 'foundation', 'recall', 'AO1'),
  (3, 'Atoms, isotopes and the development of the atomic model', 'What happens when an electron in an atom absorbs electromagnetic radiation?', 'It turns into a proton', 'It moves into the nucleus', 'It moves to a lower energy level, closer to the nucleus', 'It moves to a higher energy level, further from the nucleus', 'D', 'Absorbing radiation gives the electron energy, so it moves to a higher energy level. When it falls back down, it emits radiation.', 'foundation', 'recall', 'AO1'),
  (4, 'Atoms, isotopes and the development of the atomic model', 'A neutral atom loses one of its outer electrons. What does it become?', 'A negative ion', 'A positive ion', 'A different isotope of the same element', 'An atom of a different element', 'B', 'It now has one more proton than electrons, so it has an overall positive charge. The nucleus is unchanged, so it is the same element and isotope.', 'foundation', 'applied', 'AO2'),
  (5, 'Atoms, isotopes and the development of the atomic model', 'Carbon-14 has an atomic number of 6. How many neutrons are in its nucleus?', '20', '14', '6', '8', 'D', 'Neutrons = mass number − atomic number = 14 − 6 = 8.', 'foundation', 'calculation', 'AO2'),
  (6, 'Radioactive decay, nuclear radiation and nuclear equations', 'Which type of nuclear radiation is the most ionising?', 'Beta', 'Neutron', 'Gamma', 'Alpha', 'D', 'Alpha particles are large and have a 2+ charge, so they ionise strongly. Because of this they also have the shortest range.', 'foundation', 'recall', 'AO1'),
  (7, 'Radioactive decay, nuclear radiation and nuclear equations', 'A type of radiation passes through paper but is stopped by a few millimetres of aluminium. What type is it?', 'Beta', 'Alpha', 'Gamma', 'None of these: all radiation is stopped by paper', 'A', 'Alpha is stopped by paper, beta by a few mm of aluminium, and gamma is only reduced by thick lead or concrete.', 'foundation', 'applied', 'AO2'),
  (8, 'Radioactive decay, nuclear radiation and nuclear equations', 'Uranium-238 (atomic number 92) decays by emitting an alpha particle. What are the mass number and atomic number of the new nucleus?', 'Mass number 236, atomic number 91', 'Mass number 234, atomic number 90', 'Mass number 234, atomic number 92', 'Mass number 238, atomic number 90', 'B', 'An alpha particle is ⁴₂He, so the mass number falls by 4 (238 → 234) and the atomic number falls by 2 (92 → 90).', 'foundation', 'calculation', 'AO2'),
  (9, 'Radioactive decay, nuclear radiation and nuclear equations', 'What happens in the nucleus during beta decay?', 'A neutron changes into a proton and an electron, so the atomic number increases by 1', 'A proton changes into a neutron, so the atomic number decreases by 1', 'An electron from an outer shell is emitted', 'The mass number decreases by 4', 'A', 'In beta decay a neutron becomes a proton and a high-speed electron is emitted from the nucleus. The mass number stays the same and the atomic number goes up by 1.', 'higher', 'recall', 'AO1'),
  (10, 'Radioactive decay, nuclear radiation and nuclear equations', 'How does emitting gamma radiation change a nucleus?', 'Both numbers decrease by 1', 'Neither the mass number nor the atomic number changes', 'The atomic number increases by 1', 'The mass number decreases by 4', 'B', 'Gamma rays are electromagnetic waves with no mass or charge. Emitting one carries away energy but doesn''t change the number of protons or neutrons.', 'foundation', 'recall', 'AO1'),
  (11, 'Half-life, contamination and irradiation', 'What is meant by the half-life of a radioactive isotope?', 'The time it takes for the number of unstable nuclei in a sample (or its activity) to halve', 'The time it takes for all the nuclei in a sample to decay', 'Half the time it takes for a sample to decay completely', 'The time it takes for one nucleus to decay', 'A', 'Radioactive decay is random, so we can''t say when one nucleus will decay, but the time for half the nuclei to decay is fixed for each isotope.', 'foundation', 'recall', 'AO1'),
  (12, 'Half-life, contamination and irradiation', 'A sample has an activity of 800 Bq and a half-life of 2 hours. What is its activity after 6 hours?', '400 Bq', '267 Bq', '100 Bq', '200 Bq', 'C', '6 hours is 3 half-lives: 800 → 400 → 200 → 100 Bq.', 'foundation', 'calculation', 'AO2'),
  (13, 'Half-life, contamination and irradiation', 'A sample contains 1000 unstable nuclei. How many of them have decayed after two half-lives?', '500', '1000', '250', '750', 'D', 'After one half-life 500 remain; after two, 250 remain. So 1000 − 250 = 750 have decayed. 250 is the number left, not the number decayed.', 'higher', 'calculation', 'AO3'),
  (14, 'Half-life, contamination and irradiation', 'What is the difference between radioactive contamination and irradiation?', 'They mean the same thing', 'Contamination only happens with gamma rays; irradiation only happens with alpha particles', 'Contamination is when radioactive atoms get onto or into an object; irradiation is exposure to radiation without the object becoming radioactive', 'Irradiation is when radioactive atoms get onto an object; contamination is exposure to radiation only', 'C', 'An irradiated object does not become radioactive. A contaminated object carries the radioactive source with it, so the exposure continues.', 'foundation', 'recall', 'AO1'),
  (15, 'Half-life, contamination and irradiation', 'What is the unit of radioactive activity?', 'Joule (J)', 'Sievert (Sv)', 'Hertz (Hz)', 'Becquerel (Bq)', 'D', 'Activity is the rate at which nuclei decay, measured in becquerels (decays per second). The sievert measures radiation dose.', 'foundation', 'recall', 'AO1'),
  (16, 'Background radiation, uses of radiation, fission and fusion', 'What happens in nuclear fission?', 'Electrons are removed from an atom', 'A nucleus emits an alpha particle', 'A large unstable nucleus splits into two smaller nuclei, releasing energy and two or three neutrons', 'Two light nuclei join to form a heavier nucleus', 'C', 'Fission is usually triggered by the nucleus absorbing a neutron. The neutrons released can cause further fissions in a chain reaction.', 'foundation', 'recall', 'AO1'),
  (17, 'Background radiation, uses of radiation, fission and fusion', 'How is the chain reaction controlled in a nuclear reactor?', 'The moderator adds extra neutrons', 'The coolant produces more neutrons', 'Control rods absorb some of the neutrons', 'The concrete shielding speeds up the neutrons', 'C', 'Lowering the control rods absorbs more neutrons, so fewer fissions happen. The moderator slows neutrons down so they can be absorbed by fuel nuclei.', 'foundation', 'recall', 'AO1'),
  (18, 'Background radiation, uses of radiation, fission and fusion', 'What happens in nuclear fusion?', 'Two light nuclei join to form a heavier nucleus, releasing energy', 'Electrons combine with protons in the nucleus', 'A star collapses to form a black hole', 'A heavy nucleus splits into two lighter nuclei', 'A', 'Fusion powers stars. Some of the mass of the light nuclei is converted into energy.', 'foundation', 'recall', 'AO1'),
  (19, 'Background radiation, uses of radiation, fission and fusion', 'Why are gamma emitters used as medical tracers inside the body rather than alpha emitters?', 'Alpha emitters are not radioactive', 'Gamma emitters always have very long half-lives', 'Alpha particles are more penetrating than gamma rays', 'Gamma rays can pass out of the body to be detected and are much less ionising', 'D', 'A tracer must be detected from outside the body, so its radiation must be penetrating. Alpha would be absorbed inside the body and is very ionising, so it would cause more damage. Tracers also have short half-lives.', 'higher', 'applied', 'AO3'),
  (20, 'Background radiation, uses of radiation, fission and fusion', 'Which of these is a natural source of background radiation?', 'Mobile phone masts', 'Radon gas from rocks such as granite', 'Radio broadcasts', 'Wi-Fi routers', 'B', 'Background radiation comes from natural sources such as rocks and cosmic rays, and from man-made sources such as nuclear accidents and medical X-rays. Radio waves and microwaves are not nuclear radiation.', 'foundation', 'recall', 'AO1')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Atomic Structure') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

