insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'f4523abc-cc13-426c-9eed-deef288ff03d'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Scalars, vectors, weight and resultant forces', 'Which of these is a vector quantity?', 'Energy', 'Velocity', 'Mass', 'Speed', 'B', 'A vector has magnitude and direction. Velocity is speed in a given direction; speed, mass and energy are scalars.', 'foundation', 'recall', 'AO1'),
  (2, 'Scalars, vectors, weight and resultant forces', 'What is the weight of a 60 kg person on Earth? (g = 9.8 N/kg)', '6.1 N', '60 N', '588 N', '5880 N', 'C', 'W = mg = 60 × 9.8 = 588 N. Mass is measured in kg; weight is a force measured in newtons.', 'foundation', 'calculation', 'AO2'),
  (3, 'Scalars, vectors, weight and resultant forces', 'A box has a force of 8 N acting to the right and a force of 3 N acting to the left. What is the resultant force?', '11 N to the right', '5 N to the left', '24 N to the right', '5 N to the right', 'D', 'Forces in opposite directions are subtracted: 8 − 3 = 5 N, in the direction of the larger force.', 'foundation', 'calculation', 'AO2'),
  (4, 'Work done and energy transfer', 'A force of 50 N pushes a box 4.0 m along the floor in the direction of the force. How much work is done?', '200 J', '54 J', '2000 J', '12.5 J', 'A', 'W = Fs = 50 × 4.0 = 200 J.', 'foundation', 'calculation', 'AO2'),
  (5, 'Work done and energy transfer', 'One joule of work is done when…', 'a force of 1 N moves an object 1 m in the direction of the force', 'a force of 1 N acts on a mass of 1 kg', 'a mass of 1 kg moves 1 m', 'a force of 1 N acts for 1 second', 'A', 'Work done = force × distance moved along the line of action of the force, so 1 J = 1 N m.', 'foundation', 'recall', 'AO1'),
  (6, 'Forces and elasticity', 'A spring has a spring constant of 40 N/m. What force is needed to stretch it by 0.050 m?', '2.0 N', '40 N', '800 N', '0.00125 N', 'A', 'F = ke = 40 × 0.050 = 2.0 N. The extension must be in metres.', 'foundation', 'calculation', 'AO2'),
  (7, 'Forces and elasticity', 'What happens when a spring is stretched beyond its limit of proportionality?', 'The extension is no longer directly proportional to the force applied', 'The spring snaps immediately', 'The spring stores no energy', 'The spring constant doubles', 'A', 'Up to the limit of proportionality, F = ke. Beyond it the force–extension graph curves and the spring may not return to its original length.', 'foundation', 'recall', 'AO1'),
  (8, 'Forces and elasticity', 'What is meant by elastic deformation?', 'The object stays permanently stretched', 'The object''s mass increases', 'The object returns to its original shape and size when the forces are removed', 'The object breaks into pieces', 'C', 'If it doesn''t return to its original shape, the deformation is inelastic.', 'foundation', 'recall', 'AO1'),
  (9, 'Moments, levers and gears', 'A force of 20 N acts at a perpendicular distance of 0.30 m from a pivot. What is the moment?', '66.7 N m', '0.015 N m', '6.0 N m', '20.3 N m', 'C', 'M = Fd = 20 × 0.30 = 6.0 N m.', 'foundation', 'calculation', 'AO2'),
  (10, 'Moments, levers and gears', 'A seesaw is balanced. A child weighing 400 N sits 1.5 m from the pivot. A second child sits 2.0 m from the pivot on the other side. What is the second child''s weight?', '300 N', '600 N', '533 N', '800 N', 'A', 'For balance, clockwise moment = anticlockwise moment: 400 × 1.5 = W × 2.0, so W = 600 ÷ 2.0 = 300 N.', 'foundation', 'calculation', 'AO2'),
  (11, 'Moments, levers and gears', 'A small gear drives a larger gear. Compared with the small gear, how does the larger gear turn?', 'At the same speed, with the same moment', 'Faster, with a smaller moment', 'More slowly, but with a larger moment', 'Faster, with a larger moment', 'C', 'The larger gear has a bigger radius, so the same force gives a bigger moment, but it turns fewer times. Gears like this are used to increase the turning effect.', 'higher', 'applied', 'AO3'),
  (12, 'Pressure in fluids', 'A force of 600 N acts on an area of 0.020 m². What pressure does it exert?', '1200 Pa', '3000 Pa', '12 Pa', '30 000 Pa', 'D', 'p = F/A = 600 ÷ 0.020 = 30 000 Pa.', 'foundation', 'calculation', 'AO2'),
  (13, 'Pressure in fluids', 'What is the pressure due to a 10 m column of water? (density of water = 1000 kg/m³, g = 9.8 N/kg)', '980 Pa', '9800 Pa', '98 000 Pa', '10 000 Pa', 'C', 'p = hρg = 10 × 1000 × 9.8 = 98 000 Pa. Pressure in a liquid increases with depth because of the weight of liquid above.', 'higher', 'calculation', 'AO2'),
  (14, 'Describing motion: speed, velocity, acceleration and graphs', 'A runner covers 100 m in 12.5 s. What is their average speed?', '87.5 m/s', '0.125 m/s', '8.0 m/s', '1250 m/s', 'C', 'Speed = distance ÷ time = 100 ÷ 12.5 = 8.0 m/s.', 'foundation', 'calculation', 'AO2'),
  (15, 'Describing motion: speed, velocity, acceleration and graphs', 'A car accelerates from rest to 20 m/s in 4.0 s. What is its acceleration?', '0.20 m/s²', '80 m/s²', '5.0 m/s²', '24 m/s²', 'C', 'a = Δv/t = (20 − 0) ÷ 4.0 = 5.0 m/s².', 'foundation', 'calculation', 'AO2'),
  (16, 'Describing motion: speed, velocity, acceleration and graphs', 'What does the area under a velocity–time graph represent?', 'The acceleration', 'The speed', 'The resultant force', 'The distance travelled', 'D', 'Area under a velocity–time graph = distance travelled. The gradient of a velocity–time graph is the acceleration.', 'foundation', 'recall', 'AO1'),
  (17, 'Describing motion: speed, velocity, acceleration and graphs', 'A car travelling at 30 m/s brakes with a constant deceleration of 5.0 m/s². How far does it travel before stopping?', '6.0 m', '45 m', '180 m', '90 m', 'D', 'v² − u² = 2as: 0 − 30² = 2 × (−5.0) × s, so s = 900 ÷ 10 = 90 m.', 'higher', 'calculation', 'AO2'),
  (18, 'Newton''s laws of motion', 'What resultant force is needed to give a 1200 kg car an acceleration of 2.0 m/s²?', '0.0017 N', '600 N', '1202 N', '2400 N', 'D', 'F = ma = 1200 × 2.0 = 2400 N.', 'foundation', 'calculation', 'AO2'),
  (19, 'Newton''s laws of motion', 'A car is travelling at a constant velocity. What can you say about the forces on it?', 'There is a resultant force in the direction of motion', 'No forces act on it', 'The driving force is bigger than the resistive forces', 'The resultant force on it is zero', 'D', 'Newton''s first law: if the velocity is constant, the forces are balanced, so the resultant force is zero.', 'foundation', 'applied', 'AO2'),
  (20, 'Newton''s laws of motion', 'A person pushes on a wall with a force of 50 N. According to Newton''s third law, what force does the wall exert?', '50 N on the person, in the same direction', 'No force, because the wall doesn''t move', '50 N on the person, in the opposite direction', 'Less than 50 N, because the wall is fixed', 'C', 'Newton''s third law: when two objects interact, they exert equal and opposite forces on each other. The forces act on different objects.', 'foundation', 'recall', 'AO1'),
  (21, 'Stopping distances', 'Which factor increases a driver''s thinking distance?', 'Icy roads', 'Worn tyres', 'Wet roads', 'The driver being tired', 'D', 'Thinking distance depends on reaction time and speed. Tiredness, alcohol, drugs and distractions slow reactions. Road and tyre conditions affect braking distance.', 'foundation', 'applied', 'AO2'),
  (22, 'Stopping distances', 'A car is travelling at 20 m/s. The driver''s reaction time is 0.70 s. What is the thinking distance?', '20.7 m', '28.6 m', '14 m', '0.035 m', 'C', 'Thinking distance = speed × reaction time = 20 × 0.70 = 14 m.', 'foundation', 'calculation', 'AO2'),
  (23, 'Momentum', 'What is the momentum of a 0.50 kg ball moving at 4.0 m/s?', '8.0 kg m/s', '2.0 kg m/s', '0.125 kg m/s', '4.5 kg m/s', 'B', 'p = mv = 0.50 × 4.0 = 2.0 kg m/s.', 'foundation', 'calculation', 'AO2'),
  (24, 'Momentum', 'A 2.0 kg trolley moving at 3.0 m/s collides with a stationary 1.0 kg trolley and they stick together. What is their velocity just after the collision?', '1.5 m/s', '3.0 m/s', '2.0 m/s', '6.0 m/s', 'C', 'Momentum is conserved. Before: 2.0 × 3.0 = 6.0 kg m/s. After: (2.0 + 1.0) × v = 6.0, so v = 2.0 m/s.', 'higher', 'calculation', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Forces') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

