insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'f4523abc-cc13-426c-9eed-deef288ff03d'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Transverse and longitudinal waves and the wave equation', 'A wave has a frequency of 50 Hz and a wavelength of 0.40 m. What is its speed?', '0.008 m/s', '125 m/s', '20 m/s', '50.4 m/s', 'C', 'v = fλ = 50 × 0.40 = 20 m/s.', 'foundation', 'calculation', 'AO2'),
  (2, 'Transverse and longitudinal waves and the wave equation', 'Which of these is a longitudinal wave?', 'Sound waves in air', 'Radio waves', 'Ripples on the surface of water', 'Light waves', 'A', 'In a longitudinal wave the oscillations are parallel to the direction of energy transfer. Electromagnetic waves and water ripples are transverse.', 'foundation', 'recall', 'AO1'),
  (3, 'Transverse and longitudinal waves and the wave equation', 'What is the amplitude of a wave?', 'The number of waves passing a point each second', 'The distance from one crest to the next crest', 'The distance from a crest to a trough', 'The maximum displacement of a point on the wave from its undisturbed position', 'D', 'Amplitude is measured from the rest position to a crest. Crest to crest is the wavelength, and crest to trough is twice the amplitude.', 'foundation', 'recall', 'AO1'),
  (4, 'Transverse and longitudinal waves and the wave equation', 'A wave has a frequency of 25 Hz. What is its period?', '25 s', '0.4 s', '2.5 s', '0.04 s', 'D', 'T = 1/f = 1 ÷ 25 = 0.04 s.', 'foundation', 'calculation', 'AO2'),
  (5, 'Reflection, sound, ultrasound and seismic waves', 'What is ultrasound?', 'Sound with a frequency above 20 000 Hz', 'Sound with a frequency below 20 Hz', 'An electromagnetic wave', 'Sound between 20 Hz and 20 000 Hz', 'A', 'Ultrasound is above the upper limit of human hearing (20 kHz). Below 20 Hz is infrasound.', 'foundation', 'recall', 'AO1'),
  (6, 'Reflection, sound, ultrasound and seismic waves', 'A ship sends an ultrasound pulse to the sea bed. The echo returns after 0.40 s. Sound travels at 1500 m/s in sea water. How deep is the water?', '600 m', '300 m', '150 m', '3750 m', 'B', 'Distance travelled = 1500 × 0.40 = 600 m, but that is there and back, so the depth is 600 ÷ 2 = 300 m.', 'foundation', 'calculation', 'AO2'),
  (7, 'Reflection, sound, ultrasound and seismic waves', 'S-waves cannot travel through the Earth''s outer core. What does this suggest?', 'The outer core is liquid', 'The outer core is hollow', 'The outer core is solid', 'The outer core is made of iron', 'A', 'S-waves are transverse and cannot travel through liquids. The S-wave shadow zone is evidence that the outer core is liquid.', 'higher', 'applied', 'AO3'),
  (8, 'Reflection, sound, ultrasound and seismic waves', 'What is the range of normal human hearing?', '20 Hz to 20 kHz', '2 Hz to 2 kHz', '20 kHz to 20 MHz', '200 Hz to 200 kHz', 'A', 'Humans hear frequencies from about 20 Hz to 20 000 Hz. The ear converts sound waves into vibrations of solids, which only works over this range.', 'foundation', 'recall', 'AO1'),
  (9, 'Electromagnetic waves: properties, uses and hazards', 'Which type of electromagnetic wave has the longest wavelength?', 'Visible light', 'Radio waves', 'Microwaves', 'Gamma rays', 'B', 'In order of increasing wavelength: gamma, X-rays, ultraviolet, visible, infrared, microwaves, radio.', 'foundation', 'recall', 'AO1'),
  (10, 'Electromagnetic waves: properties, uses and hazards', 'What do all electromagnetic waves have in common?', 'They are all longitudinal', 'They all travel at the same speed in a vacuum', 'They all have the same frequency', 'They all have the same wavelength', 'B', 'All electromagnetic waves are transverse and travel at the same speed (3 × 10⁸ m/s) through a vacuum.', 'foundation', 'recall', 'AO1'),
  (11, 'Electromagnetic waves: properties, uses and hazards', 'Which type of electromagnetic wave is used to communicate with satellites?', 'Ultraviolet', 'Gamma rays', 'X-rays', 'Microwaves', 'D', 'Microwaves can pass through the atmosphere, so they are used for satellite communications.', 'foundation', 'recall', 'AO1'),
  (12, 'Electromagnetic waves: properties, uses and hazards', 'Which is a hazard of ultraviolet radiation?', 'It has no effect on living cells', 'It is completely absorbed by clothing so it cannot reach the skin', 'It can make skin age prematurely and increase the risk of skin cancer', 'It can damage the ears', 'C', 'Ultraviolet is ionising at the high-frequency end. It can damage skin cells and DNA, causing sunburn, premature ageing and skin cancer.', 'foundation', 'recall', 'AO1'),
  (13, 'Lenses', 'An object 2.0 cm tall produces an image 6.0 cm tall through a lens. What is the magnification?', '0.33', '12', '3', '4', 'C', 'Magnification = image height ÷ object height = 6.0 ÷ 2.0 = 3. It has no units.', 'foundation', 'calculation', 'AO2'),
  (14, 'Lenses', 'What does a convex lens do to parallel rays of light?', 'Brings them together at the principal focus', 'Spreads them out so they appear to come from the principal focus', 'Absorbs them', 'Reflects them back towards the source', 'A', 'A convex (converging) lens brings parallel rays to a point. A concave (diverging) lens spreads them out.', 'foundation', 'recall', 'AO1'),
  (15, 'Lenses', 'What type of image does a concave lens always produce?', 'A magnified image', 'A virtual image', 'An inverted image', 'A real image', 'B', 'A concave lens always produces a virtual, upright, diminished image. A convex lens can produce real or virtual images.', 'higher', 'recall', 'AO1'),
  (16, 'Visible light and colour', 'Why does a red object look red in white light?', 'It reflects red light and absorbs the other colours', 'It transmits all colours equally', 'It produces its own red light', 'It absorbs red light and reflects the other colours', 'A', 'The colour of an opaque object depends on which wavelengths it reflects most.', 'foundation', 'recall', 'AO1'),
  (17, 'Visible light and colour', 'A red object is viewed in blue light only. What colour does it appear?', 'Blue', 'White', 'Red', 'Black', 'D', 'The red object absorbs blue light and there is no red light to reflect, so no light reaches the eye from it.', 'foundation', 'applied', 'AO3'),
  (18, 'Black body radiation', 'What is a perfect black body?', 'An object that only emits visible light', 'An object that absorbs all the radiation that falls on it', 'An object that reflects all the radiation that falls on it', 'An object that emits no radiation', 'B', 'A perfect black body absorbs all incident radiation, does not reflect or transmit any, and is also the best possible emitter.', 'foundation', 'recall', 'AO1'),
  (19, 'Black body radiation', 'How does the radiation emitted by a body change as its temperature increases?', 'It only emits infrared', 'It emits less radiation, mostly at longer wavelengths', 'It emits the same amount of radiation', 'It emits more radiation in total, and a higher proportion at shorter wavelengths', 'D', 'Hotter bodies emit more radiation, and the peak shifts to shorter wavelengths. That is why very hot objects glow red, then white.', 'higher', 'applied', 'AO3'),
  (20, 'Black body radiation', 'An object''s temperature is staying constant. What can you say about the radiation it absorbs and emits?', 'It emits no radiation', 'It absorbs no radiation', 'It absorbs radiation at the same rate as it emits radiation', 'It absorbs radiation faster than it emits it', 'C', 'A body at constant temperature is in balance: its rate of absorption equals its rate of emission. If it absorbs faster, its temperature rises.', 'foundation', 'applied', 'AO3')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Waves') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

