insert into topics (subject_id, name, spec_ref, paper, display_order) values ((select id from subjects where name = 'Physics'), 'Magnetism and Electromagnetism', 'P7', 'Paper 2', 7);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Magnetism and Electromagnetism'), 'Permanent and induced magnetism and magnetic fields', '4.7.1', 1);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Magnetism and Electromagnetism'), 'Electromagnetism and the motor effect', '4.7.2', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Magnetism and Electromagnetism'), 'Induced potential, generators and transformers', '4.7.3', 3);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'f4523abc-cc13-426c-9eed-deef288ff03d'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Permanent and induced magnetism and magnetic fields', 'Two magnets are placed with their north poles facing each other. What happens?', 'They repel', 'They attract', 'Nothing happens', 'They become induced magnets', 'A', 'Like poles repel and unlike poles attract.', 'foundation', 'recall', 'AO1'),
  (2, 'Permanent and induced magnetism and magnetic fields', 'Which way do magnetic field lines point?', 'From the south pole to the north pole', 'Straight out from both poles', 'In circles around each pole', 'From the north pole to the south pole', 'D', 'The direction of a magnetic field line is the direction of the force on a north pole at that point, which is from north to south outside a magnet.', 'foundation', 'recall', 'AO1'),
  (3, 'Permanent and induced magnetism and magnetic fields', 'What is an induced magnet?', 'A magnet made only from nickel', 'A magnet that always repels permanent magnets', 'A magnet that produces its own permanent magnetic field', 'A material that becomes a magnet only while it is in a magnetic field', 'D', 'Induced magnets always attract permanent magnets and lose most or all of their magnetism when removed from the field.', 'foundation', 'recall', 'AO1'),
  (4, 'Permanent and induced magnetism and magnetic fields', 'Which of these is a magnetic material?', 'Nickel', 'Aluminium', 'Copper', 'Brass', 'A', 'The magnetic materials are iron, steel, cobalt and nickel.', 'foundation', 'recall', 'AO1'),
  (5, 'Permanent and induced magnetism and magnetic fields', 'Where is the magnetic field of a bar magnet strongest?', 'Equally strong everywhere', 'Far away from the magnet', 'In the middle of the magnet', 'At the poles', 'D', 'Field lines are closest together at the poles, which shows the field is strongest there.', 'foundation', 'recall', 'AO1'),
  (6, 'Permanent and induced magnetism and magnetic fields', 'Why does a compass needle point north?', 'It is attracted to the nearest iron object', 'It lines up with the Earth''s magnetic field, which is produced by its core', 'It is pulled by the Earth''s gravity', 'It is attracted to the North Star', 'B', 'A compass contains a small bar magnet that lines up with the magnetic field. The Earth''s field is evidence that its core is magnetic.', 'foundation', 'applied', 'AO2'),
  (7, 'Electromagnetism and the motor effect', 'What is the shape of the magnetic field around a long straight wire carrying a current?', 'There is no magnetic field', 'Concentric circles around the wire', 'Straight lines parallel to the wire', 'Lines radiating out from the wire', 'B', 'The field forms circles centred on the wire. Its strength decreases with distance from the wire and increases with the current.', 'foundation', 'recall', 'AO1'),
  (8, 'Electromagnetism and the motor effect', 'Which change makes an electromagnet stronger?', 'Using a copper core', 'Using fewer turns of wire', 'Reversing the current', 'Adding an iron core', 'D', 'An iron core, more turns or a bigger current all increase the strength. Reversing the current just reverses the poles.', 'foundation', 'applied', 'AO2'),
  (9, 'Electromagnetism and the motor effect', 'What is the magnetic field like inside a long solenoid?', 'Strong and uniform', 'Zero', 'Weak and changing in direction', 'Circular around the solenoid''s axis', 'A', 'Inside a solenoid the field lines are parallel and close together, so the field is strong and uniform, like that of a bar magnet outside.', 'foundation', 'recall', 'AO1'),
  (10, 'Electromagnetism and the motor effect', 'A wire 0.50 m long carries a current of 3.0 A at right angles to a magnetic field of flux density 0.20 T. What is the force on the wire?', '30 N', '0.30 N', '1.2 N', '3.7 N', 'B', 'F = BIl = 0.20 × 3.0 × 0.50 = 0.30 N.', 'higher', 'calculation', 'AO2'),
  (11, 'Electromagnetism and the motor effect', 'In Fleming''s left-hand rule, what does the first finger represent?', 'The direction of the force', 'The direction of the current', 'The direction of the magnetic field', 'The potential difference', 'C', 'First finger = Field, seCond finger = Current, thuMb = Motion (force).', 'foundation', 'recall', 'AO1'),
  (12, 'Electromagnetism and the motor effect', 'Which change would make a simple d.c. electric motor spin faster?', 'Reversing the magnetic field', 'Using a plastic coil instead of copper', 'Reversing the direction of the current', 'Increasing the current', 'D', 'A larger current or a stronger magnetic field increases the force on the coil. Reversing either just reverses the direction of rotation.', 'foundation', 'applied', 'AO2'),
  (13, 'Electromagnetism and the motor effect', 'How can the direction of the force on a current-carrying wire in a magnetic field be reversed?', 'Reverse the direction of the current', 'Use a longer wire', 'Increase the magnetic flux density', 'Increase the current', 'A', 'The direction of the force depends on the directions of the current and the field. Changing their sizes only changes the size of the force.', 'foundation', 'applied', 'AO2'),
  (14, 'Electromagnetism and the motor effect', 'How does a loudspeaker produce sound?', 'The magnet heats the air, which makes a sound', 'A direct current in the coil makes the cone move out and stay there', 'An alternating current in a coil in a magnetic field makes the coil and cone vibrate', 'Static charge on the cone repels the air', 'C', 'The changing current causes a changing force on the coil (the motor effect), so the cone vibrates and creates pressure waves in the air.', 'higher', 'applied', 'AO3'),
  (15, 'Induced potential, generators and transformers', 'What is the generator effect?', 'A force acts on a current-carrying wire in a magnetic field', 'A potential difference is induced when a wire moves relative to a magnetic field', 'A magnet is attracted to a current-carrying wire', 'A current makes a wire heat up', 'B', 'Moving a conductor through a field (or changing the field around it) induces a pd. If the conductor is part of a complete circuit, a current flows.', 'foundation', 'recall', 'AO1'),
  (16, 'Induced potential, generators and transformers', 'A magnet is pushed into a coil connected to a meter. Which change would increase the induced potential difference?', 'Moving the magnet more slowly', 'Moving the magnet faster', 'Holding the magnet still inside the coil', 'Using a coil with fewer turns', 'B', 'The induced pd is bigger if the magnetic field changes faster, the magnet is stronger, or the coil has more turns. A stationary magnet induces nothing.', 'foundation', 'applied', 'AO2'),
  (17, 'Induced potential, generators and transformers', 'A transformer has 1000 turns on its primary coil and 50 turns on its secondary coil. The primary pd is 230 V. What is the secondary pd?', '11.5 V', '23 V', '230 V', '4600 V', 'A', 'Vp/Vs = np/ns, so Vs = 230 × 50 ÷ 1000 = 11.5 V. This is a step-down transformer.', 'higher', 'calculation', 'AO2'),
  (18, 'Induced potential, generators and transformers', 'Why does a transformer only work with alternating current?', 'Direct current cannot flow through coils of wire', 'Direct current is too strong for the iron core', 'Alternating current carries more energy', 'Only a changing current produces a changing magnetic field, which induces a pd in the secondary coil', 'D', 'A steady d.c. gives a constant magnetic field in the core, so no pd is induced in the secondary coil.', 'higher', 'applied', 'AO3'),
  (19, 'Induced potential, generators and transformers', 'How is a step-up transformer constructed?', 'It has more turns on the secondary coil than on the primary coil', 'It has fewer turns on the secondary coil than on the primary coil', 'It has no iron core', 'It has the same number of turns on both coils', 'A', 'More secondary turns gives a larger secondary pd, because Vp/Vs = np/ns.', 'foundation', 'recall', 'AO1'),
  (20, 'Induced potential, generators and transformers', 'A 100% efficient transformer has a primary pd of 230 V and a primary current of 0.50 A. The secondary pd is 23 V. What is the secondary current?', '2.3 A', '115 A', '0.050 A', '5.0 A', 'D', 'For a 100% efficient transformer, Vp × Ip = Vs × Is: 230 × 0.50 = 23 × Is, so Is = 115 ÷ 23 = 5.0 A.', 'higher', 'calculation', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Magnetism and Electromagnetism') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

insert into quizzes (topic_id, title, display_order, question_count, cooldown_hours) values ((select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Magnetism and Electromagnetism'), 'Quiz 1', 1, 0, 168);
with ordered as (
  select q.id, row_number() over (order by q.created_at) - 1 as i
  from questions q join subtopics s on s.id = q.subtopic_id
  where q.generation_batch_id = 'f4523abc-cc13-426c-9eed-deef288ff03d'::uuid and q.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Magnetism and Electromagnetism')
)
insert into quiz_questions (quiz_id, question_id, position)
select z.id, o.id, (o.i / 1)::int + 1
from ordered o join quizzes z on z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Magnetism and Electromagnetism') and z.title = 'Quiz ' || ((o.i % 1) + 1);
update quizzes z set question_count = (select count(*) from quiz_questions qq where qq.quiz_id = z.id) where z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Magnetism and Electromagnetism');

insert into topics (subject_id, name, spec_ref, paper, display_order) values ((select id from subjects where name = 'Physics'), 'Space Physics', 'P8', 'Paper 2', 8);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Space Physics'), 'The solar system and the life cycle of a star', '4.8.1.1-4.8.1.2', 1);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Space Physics'), 'Orbital motion, natural and artificial satellites', '4.8.1.3', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Space Physics'), 'Red-shift and the Big Bang', '4.8.2', 3);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'f4523abc-cc13-426c-9eed-deef288ff03d'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'The solar system and the life cycle of a star', 'Which galaxy is our solar system part of?', 'Andromeda', 'The Sun is not in a galaxy', 'The Large Magellanic Cloud', 'The Milky Way', 'D', 'Our solar system is one small part of the Milky Way galaxy.', 'foundation', 'recall', 'AO1'),
  (2, 'The solar system and the life cycle of a star', 'What does a star form from?', 'A white dwarf', 'A planet that has become very hot', 'A black hole', 'A cloud of dust and gas (a nebula) pulled together by gravity', 'D', 'Gravity pulls the dust and gas together into a protostar. As it gets hotter and denser, fusion starts.', 'foundation', 'recall', 'AO1'),
  (3, 'The solar system and the life cycle of a star', 'Why is a main sequence star stable for a long time?', 'No forces act on it', 'The outward pressure from fusion balances the inward pull of gravity', 'Fusion has stopped inside it', 'Gravity alone holds it in shape', 'B', 'During the main sequence these forces are in equilibrium, so the star neither expands nor collapses.', 'foundation', 'recall', 'AO1'),
  (4, 'The solar system and the life cycle of a star', 'What does a star about the same size as the Sun become when it leaves the main sequence?', 'A supernova', 'A neutron star', 'A red super giant', 'A red giant', 'D', 'Sun-sized stars become red giants, then white dwarfs. Much bigger stars become red super giants and then explode as supernovae.', 'foundation', 'recall', 'AO1'),
  (5, 'The solar system and the life cycle of a star', 'What happens at the end of the life of a star much more massive than the Sun?', 'It turns back into a nebula without exploding', 'It explodes as a supernova, leaving a neutron star or a black hole', 'It becomes a main sequence star again', 'It becomes a white dwarf and then a black dwarf', 'B', 'Very massive stars become red super giants, then supernovae. The core that remains becomes a neutron star or, for the most massive, a black hole.', 'foundation', 'recall', 'AO1'),
  (6, 'The solar system and the life cycle of a star', 'Where are elements heavier than iron produced?', 'Inside planets', 'By fusion in main sequence stars', 'In supernova explosions', 'In the first few seconds of the Big Bang', 'C', 'Fusion in stars can only build elements up to iron. Heavier elements form in supernovae and are spread through the universe by the explosion.', 'higher', 'recall', 'AO1'),
  (7, 'The solar system and the life cycle of a star', 'Which is the correct life cycle of a star about the same size as the Sun?', 'Nebula → main sequence → supernova → red giant → black hole', 'Nebula → protostar → main sequence → red giant → white dwarf → black dwarf', 'Nebula → protostar → main sequence → red super giant → supernova → neutron star', 'Protostar → nebula → main sequence → white dwarf → red giant', 'B', 'The second option is the life cycle of a much more massive star.', 'foundation', 'recall', 'AO1'),
  (8, 'The solar system and the life cycle of a star', 'What fusion reaction happens in the core of a main sequence star?', 'Hydrogen nuclei fuse to form helium', 'Iron nuclei fuse to form uranium', 'Carbon nuclei split to form hydrogen', 'Helium nuclei split to form hydrogen', 'A', 'Main sequence stars fuse hydrogen into helium, which releases energy.', 'foundation', 'recall', 'AO1'),
  (9, 'Orbital motion, natural and artificial satellites', 'What force keeps planets in orbit around the Sun?', 'Friction', 'Gravity', 'Magnetism', 'Air resistance', 'B', 'The Sun''s gravitational pull provides the force that keeps planets moving in their orbits.', 'foundation', 'recall', 'AO1'),
  (10, 'Orbital motion, natural and artificial satellites', 'A satellite moves in a circular orbit at a constant speed. Why is its velocity changing?', 'Its mass is constantly changing', 'Its direction of motion is constantly changing', 'Its speed is constantly changing', 'No force acts on it', 'B', 'Velocity is a vector, so a change of direction is a change of velocity. Gravity provides the resultant force that causes this acceleration towards the centre.', 'higher', 'applied', 'AO3'),
  (11, 'Orbital motion, natural and artificial satellites', 'For an object to stay in a stable orbit closer to a planet, how must its speed change?', 'It must stop moving', 'Its speed must stay the same', 'It must move faster', 'It must move more slowly', 'C', 'Gravity is stronger closer in, so the object must move faster to stay in a stable orbit with a smaller radius.', 'higher', 'applied', 'AO3'),
  (12, 'Orbital motion, natural and artificial satellites', 'Which of these is a natural satellite?', 'The Hubble Space Telescope', 'The Moon', 'A GPS satellite', 'The International Space Station', 'B', 'Natural satellites (moons) orbit planets. The others are artificial satellites placed in orbit by people.', 'foundation', 'recall', 'AO1'),
  (13, 'Orbital motion, natural and artificial satellites', 'In which direction does the resultant force on an orbiting satellite act?', 'There is no resultant force', 'Away from the centre of the orbit', 'Towards the centre of the orbit', 'In the direction the satellite is moving', 'C', 'Gravity pulls the satellite towards the centre of the orbit. This force is at right angles to its velocity, so it changes direction but not speed.', 'foundation', 'recall', 'AO1'),
  (14, 'Orbital motion, natural and artificial satellites', 'Which of these is a dwarf planet in our solar system?', 'The Moon', 'Pluto', 'Venus', 'Mars', 'B', 'Pluto is classed as a dwarf planet. Mars and Venus are planets and the Moon is a natural satellite.', 'foundation', 'recall', 'AO1'),
  (15, 'Red-shift and the Big Bang', 'What is red-shift?', 'An observed decrease in the wavelength of light from distant galaxies', 'An observed increase in the wavelength of light from distant galaxies', 'An increase in the brightness of distant galaxies', 'An increase in the frequency of light from distant galaxies', 'B', 'Light from galaxies moving away from us is shifted towards the red end of the spectrum: longer wavelength and lower frequency.', 'foundation', 'recall', 'AO1'),
  (16, 'Red-shift and the Big Bang', 'More distant galaxies show a greater red-shift. What does this suggest?', 'The universe is contracting', 'More distant galaxies are moving towards us', 'More distant galaxies are moving away faster, so the universe is expanding', 'The universe is not changing in size', 'C', 'The greater the red-shift, the faster a galaxy is receding. This pattern is evidence that the universe is expanding.', 'foundation', 'applied', 'AO3'),
  (17, 'Red-shift and the Big Bang', 'What does the Big Bang theory suggest?', 'The universe formed from the Milky Way', 'The universe began from a very small region that was extremely hot and dense', 'The universe began as a cold, empty space', 'The universe has always existed and has not changed', 'B', 'Red-shift observations support the idea that the universe began from a tiny, hot, dense region and has been expanding ever since.', 'foundation', 'recall', 'AO1'),
  (18, 'Red-shift and the Big Bang', 'Since 1998, what have observations of supernovae suggested about the universe?', 'The universe has stopped expanding', 'The universe has started to contract', 'Distant galaxies are receding ever faster, so the expansion is accelerating', 'The expansion of the universe is slowing down', 'C', 'Observations of very distant supernovae suggest the expansion is speeding up, which scientists explain using dark energy.', 'higher', 'recall', 'AO1'),
  (19, 'Red-shift and the Big Bang', 'Which statement about dark mass and dark energy is correct?', 'They are not yet understood, and scientists are still investigating them', 'They were disproved by red-shift observations', 'They are the same as the matter that makes up stars', 'They have been fully explained by the Big Bang theory', 'A', 'There is still much about the universe that is not understood. Dark mass and dark energy are ideas scientists use to explain observations.', 'foundation', 'recall', 'AO1'),
  (20, 'Red-shift and the Big Bang', 'Light from a galaxy shows red-shift. What does this tell you about the galaxy?', 'It is made only of red stars', 'It is moving away from us', 'It is hotter than our Sun', 'It is moving towards us', 'B', 'Red-shift means the wavelength is stretched, which happens when the source is moving away from the observer.', 'foundation', 'applied', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physics') and name = 'Space Physics') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

